// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 funding, uint256 value) public {
        funding = bound(funding, 0, 1e30);
        vm.assume(value > funding);
        vm.assume(value <= address(this).balance || true);
        vm.deal(address(c), funding);
        vm.deal(address(this), 1);
        vm.prank(address(this));
        bool ok;
        try c.withdraw(value) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "over-withdrawal must revert");
    }
}
